# 计算方案数
def solve(n):
    # 标记完全平方数
    is_square = [False] * (n + 1)
    i = 1
    while i * i <= n:
        is_square[i * i] = True
        i += 1

    # dp[x] 表示乘积为 x 的合法有序分配方案数
    dp = [0] * (n + 1)
    dp[1] = 1  # 边界：已经恰好分完，算一种方案

    # 从小到大刷表
    for i in range(1, n + 1):
        if dp[i] == 0:
            continue
        # 枚举下一份的大小 j，要求 j 不是完全平方数
        for j in range(2, n // i + 1):
            if not is_square[j]:
                dp[i * j] += dp[i]

    return dp[n]


if __name__ == "__main__":
    n = int(input().strip())
    print(solve(n))
```

### Java

```java
import java.util.Scanner;

public class Main {

    // 计算方案数
    public static long solve(int n) {
        // 标记完全平方数
        boolean[] isSquare = new boolean[n + 1];
        for (int i = 1; i * i <= n; i++) {
            isSquare[i * i] = true;
        }

        // dp[x] 表示乘积为 x 的合法有序分配方案数
        long[] dp = new long[n + 1];
        dp[1] = 1; // 边界

        // 从小到大刷表
        for (int i = 1; i <= n; i++) {
            if (dp[i] == 0) {
                continue;
            }
            // 枚举下一份大小 j，j 不是完全平方数
            for (int j = 2; j <= n / i; j++) {
                if (!isSquare[j]) {
                    dp[i * j] += dp[i];
                }
            }
        }

        return dp[n];
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        System.out.println(solve(n));
    }
}
